void T07_FirstUnionFormation::scale_accumulators()
{
    assert(theT07_FirstUnionFormation); // unitary table must be instantiated

    double scale_factor = population_scaling_factor();
    if (scale_factor != 1.0) {
        // sum(delta(om_entrances_FOR_union_status_X_US_FIRST_UNION_PERIOD1))
        for (int cell = 0; cell < n_cells; cell++) acc[0][cell] *= scale_factor;
        // sum(delta(om_duration_FOR_union_status_X_US_NEVER_IN_UNION))
        for (int cell = 0; cell < n_cells; cell++) acc[1][cell] *= scale_factor;
    }
}

void T07_FirstUnionFormation::compute_expressions()
{
    assert(theT07_FirstUnionFormation); // unitary table must be instantiated

    for (int cell = 0; cell < n_cells; cell++ ) measure[0][cell] = (acc[0][cell] / acc[1][cell]) ;

}

