double * om_get_table_measure_address(int table_id, int measure_id, std::vector<int> indices)
{
    switch (table_id) {
        case 0: return theT01_LifeExpectancy ? theT01_LifeExpectancy->get_measure_address(measure_id, indices) : nullptr;
        case 1: return theT02_TotalPopulationByYear ? theT02_TotalPopulationByYear->get_measure_address(measure_id, indices) : nullptr;
        case 2: return theT03_FertilityByAge ? theT03_FertilityByAge->get_measure_address(measure_id, indices) : nullptr;
        case 3: return theT04_FertilityRatesByAgeGroup ? theT04_FertilityRatesByAgeGroup->get_measure_address(measure_id, indices) : nullptr;
        case 4: return theT05_CohortFertility ? theT05_CohortFertility->get_measure_address(measure_id, indices) : nullptr;
        case 5: return theT06_BirthsByUnion ? theT06_BirthsByUnion->get_measure_address(measure_id, indices) : nullptr;
        case 6: return theT07_FirstUnionFormation ? theT07_FirstUnionFormation->get_measure_address(measure_id, indices) : nullptr;
        default: assert(false); // logic guarantee
    }
    return nullptr;
}


