void Person::om_T01_LifeExpectancy_push_increment(size_t cell_in, int pending, big_counter pending_event_counter)
{
    if constexpr (om_resource_use_on) {
        ++T01_LifeExpectancy_increments;
    }
    assert(theT01_LifeExpectancy); // unitary table must be instantiated

    auto& table = theT01_LifeExpectancy;

    // Table has no margins

    // Increments and Accumulators:
    //  accumulator 0: unit
    {
        const int acc_index = 0; // accumulator index

        // Compute increment

        double dIncrement;
        dIncrement = 1.0;

        // Push increment to body cell
        {
            size_t cell = cell_in;
            auto& dAccumulator = table->acc[acc_index][cell];
            dAccumulator += dIncrement;
        }
    }
    //  accumulator 1: sum(delta(interval(duration())))
    {
        const int acc_index = 1; // accumulator index

        // Compute increment
        Time value_out = om_duration;
        auto& value_in = om_T01_LifeExpectancy_in_om_duration;

        double dIncrement;
        dIncrement = (double)value_out - (double)value_in;

        // Check increment validity when accumulator is sum, mean, or gini
        if (!std::isfinite(dIncrement)) {
            handle_invalid_table_increment(dIncrement, "T01_LifeExpectancy","duration()");
        }

        // Push increment to body cell
        {
            size_t cell = cell_in;
            auto& dAccumulator = table->acc[acc_index][cell];
            dAccumulator += dIncrement;
        }
    }
}
