void BaseEntity::initialize_simulation_runtime()
{
    entities = new std::list<BaseEntity *>;
    Person::zombies = new std::forward_list<Person *>;
    Person::available = new std::forward_list<Person *>;

    // reset resource use information for Person
    Person::resource_use_reset();

    // reset resource use information for events in Person
    Person::om_null_entity.om_DeathEvent_om_event.resource_use_reset();
    Person::om_null_entity.om_FirstPregEvent_om_event.resource_use_reset();
    Person::om_null_entity.om_Union1DissolutionEvent_om_event.resource_use_reset();
    Person::om_null_entity.om_Union1FormationEvent_om_event.resource_use_reset();
    Person::om_null_entity.om_Union2DissolutionEvent_om_event.resource_use_reset();
    Person::om_null_entity.om_Union2FormationEvent_om_event.resource_use_reset();
    Person::om_null_entity.om_UnionPeriod2Event_om_event.resource_use_reset();
    Person::om_null_entity.zzz_om_om_ss_event_om_event.resource_use_reset();
    // reset resource use information for multilinks in Person

    event_trace_on = om_event_trace_capable;
}

void BaseEntity::finalize_simulation_runtime()
{
    assert(entities->empty());
    delete entities;
    entities = nullptr;

    assert(Person::zombies->empty());
    delete Person::zombies;
    Person::zombies = nullptr;

    for (auto ent : *Person::available) {
        delete ent;
    }
    delete Person::available;
    Person::available = nullptr;

}

