// Model one-time initialization
void RunOnce(IRunBase * const i_runBase)
{
    // report model build environment
    theLog->logFormatted("Model build    : % s % s % s", omr::modelTargetOsName, omr::modelTargetConfigName, omr::modelTargetMpiUseName);

    theLog->logMsg("Prepare fixed and missing parameters");
    CHECKPOINT("checkpoint: Handle missing parameter 'AgeBaselineForm1'");
    theLog->logFormatted("Warning : parameter '%s' was missing when the model was built", "AgeBaselineForm1");
    CHECKPOINT("checkpoint: Handle missing parameter 'AgeBaselinePreg1'");
    theLog->logFormatted("Warning : parameter '%s' was missing when the model was built", "AgeBaselinePreg1");
    CHECKPOINT("checkpoint: Handle missing parameter 'CanDie'");
    theLog->logFormatted("Warning : parameter '%s' was missing when the model was built", "CanDie");
    CHECKPOINT("checkpoint: Handle missing parameter 'ProbMort'");
    theLog->logFormatted("Warning : parameter '%s' was missing when the model was built", "ProbMort");
    CHECKPOINT("checkpoint: Handle missing parameter 'SeparationDurationBaseline'");
    theLog->logFormatted("Warning : parameter '%s' was missing when the model was built", "SeparationDurationBaseline");
    CHECKPOINT("checkpoint: Handle missing parameter 'SimulationCases'");
    theLog->logFormatted("Warning : parameter '%s' was missing when the model was built", "SimulationCases");
    CHECKPOINT("checkpoint: Handle missing parameter 'SimulationSeed'");
    theLog->logFormatted("Warning : parameter '%s' was missing when the model was built", "SimulationSeed");
    CHECKPOINT("checkpoint: Handle missing parameter 'UnionDurationBaseline'");
    theLog->logFormatted("Warning : parameter '%s' was missing when the model was built", "UnionDurationBaseline");
    CHECKPOINT("checkpoint: Handle missing parameter 'UnionStatusPreg1'");
    theLog->logFormatted("Warning : parameter '%s' was missing when the model was built", "UnionStatusPreg1");
    CHECKPOINT("checkpoint: Finished handling missing parameters");

    // make a list of compute suppressed tables: tables which are not computed by the model due to suppression
    CHECKPOINT("checkpoint: Handle run-time suppressed tables");
    for (const auto & ti : om_table_name_id) {
        if (!i_runBase->isTableSuppressed(ti.second)) continue;

        // suppress this table if there are no other tables depends on it
        auto search = om_tables_required.find(ti.first);
        if (search == om_tables_required.end()) {
            om_compute_suppressed.insert(ti.first); // no other tables require this table
            continue;
        }

        // suppress this table if all dependant tables are suppressed
        bool isAny = false;
        for (auto tbl_requiring : search->second) {
            isAny = !i_runBase->isTableSuppressed(tbl_requiring.c_str());
            if (isAny) break;  // dependant table not suppressed
        }
        if (!isAny) om_compute_suppressed.insert(ti.first); // no non-suppressed table requires this table
    }

    CHECKPOINT("checkpoint: Finished run-time suppressed tables");

    CHECKPOINT("checkpoint: Finished RunOnce");
}

// Model run initialization
void RunInit(IRunBase * const i_runBase)
{
    CHECKPOINT("checkpoint: Starting RunInit");
    #if defined(_MSC_VER) && defined(_DEBUG) && defined(_ITERATOR_DEBUG_LEVEL) && _ITERATOR_DEBUG_LEVEL < 2
        theLog->logFormatted("Note : this Debug model was built with Microsoft iterator debug disabled");
    #endif

    theLog->logFormatted("Warning : model can expose microdata at run-time with output_microdata = on");

    extern void process_trace_options(IRunBase* const i_runBase);
    extern int64_t report_parameter_read_progress(int paramNumber, int paramCount, const char * name, int64_t lastTime);

    // Process model dev options for EventTrace
    CHECKPOINT("checkpoint: Call process_trace_options");
    process_trace_options(i_runBase);

    theLog->logMsg("Get scenario parameters for process");

    int64_t last_progress_ms = getMilliseconds();

    CHECKPOINT("checkpoint: Finished reading parameters");

    // Process development model run options
    CHECKPOINT("checkpoint: Call ProcessDevelopmentOptions");
    ProcessDevelopmentOptions(i_runBase);
    CHECKPOINT("checkpoint: Finished ProcessDevelopmentOptions");
    CHECKPOINT("checkpoint: Finished RunInit");
}

// Model startup method: Initialization for a simulation member
void ModelStartup(IModel * const i_model)
{
    CHECKPOINT("checkpoint: Starting ModelStartup");
    // obtain simulation member to use for log messages
    int simulation_member = i_model->subValueId();

    // reset the weight support API
    reset_weight_api();

    // Bind scenario parameter references to thread local values (for scenario parameters).
    // Until this is done scenario parameter values are undefined and cannot be used by the model.

    theLog->logFormatted("member=%d Bind scenario parameters", simulation_member);

    #ifdef OM_DEBUG_PARAMETERS

    CHECKPOINT("checkpoint: Finished binding debug version of parameters");

    #else // OM_DEBUG_PARAMETERS

    CHECKPOINT("checkpoint: Finished binding release version of parameters");

    #endif // OM_DEBUG_PARAMETERS

    { // predict memory requirements
        double memory_shared = omr::memory_MB_constant_per_instance;
        memory_shared *= omr::memory_safety_factor;
        double memory_sub = omr::memory_MB_constant_per_sub;
        memory_sub *= omr::memory_safety_factor;
        theLog->logFormatted("member=%d Predicted memory required = %d MB per parallel sub and %d MB per instance", simulation_member, (int)memory_sub, (int)memory_shared);
    }
    CHECKPOINT("checkpoint: Finished extend parameters");

    // Zero-initialize derived parameters.

    CHECKPOINT("checkpoint: Finished zero-initialize derived parameters");

    // Parameters are now ready and can be used by the model.

    theLog->logFormatted("member=%d Compute derived parameters", simulation_member);
    int mem_id = i_model->subValueId();
    int mem_count = i_model->subValueCount();
    CHECKPOINT("checkpoint: Calling before_presimulation");
    before_presimulation(mem_id, mem_count); // defined in model framework module
    // Call 0 PreSimulation functions without suffix
    // Call 0 PreSimulation functions with suffix
    CHECKPOINT("checkpoint: Finished calls to PreSimulation functions");
    CHECKPOINT("checkpoint: Calling after_presimulation");
    after_presimulation(); // defined in model framework module

    CHECKPOINT("checkpoint: Finished cumrate parameter preparation");
    theLog->logFormatted("member=%d Prepare for simulation", simulation_member);
    // Entity static initialization part 1: Initialize entity attribute offsets & null entity data members
    // Entity - Person
    CHECKPOINT("checkpoint: Initialize nullptr version of 'Person' (part 1)");
    Person::om_null_entity.om_assign_member_offsets();
    Person::om_null_entity.om_initialize_data_members0();

    // Entity static initialization part 2: Initialize null entity dependent attributes
    // Entity - Person
    CHECKPOINT("checkpoint: Initialize nullptr version of 'Person' (part 2)");
    Person::om_null_entity.om_initialize_identity_attributes();
    Person::om_null_entity.om_initialize_derived_attributes();
    Person::om_null_entity.om_reset_derived_attributes();
    CHECKPOINT("checkpoint: Finished nullptr version of entities");

    // Entity table instantiation
    CHECKPOINT("checkpoint: Allocate memory for 'T01_LifeExpectancy'");
    assert(!theT01_LifeExpectancy); 
    if (!is_suppressed_compute("T01_LifeExpectancy")) {
        theT01_LifeExpectancy = new T01_LifeExpectancy("T01_LifeExpectancy", {});
    }
    CHECKPOINT("checkpoint: Allocate memory for 'T02_TotalPopulationByYear'");
    assert(!theT02_TotalPopulationByYear); 
    if (!is_suppressed_compute("T02_TotalPopulationByYear")) {
        theT02_TotalPopulationByYear = new T02_TotalPopulationByYear("T02_TotalPopulationByYear", {101});
    }
    CHECKPOINT("checkpoint: Allocate memory for 'T03_FertilityByAge'");
    assert(!theT03_FertilityByAge); 
    if (!is_suppressed_compute("T03_FertilityByAge")) {
        theT03_FertilityByAge = new T03_FertilityByAge("T03_FertilityByAge", {27});
    }
    CHECKPOINT("checkpoint: Allocate memory for 'T04_FertilityRatesByAgeGroup'");
    assert(!theT04_FertilityRatesByAgeGroup); 
    if (!is_suppressed_compute("T04_FertilityRatesByAgeGroup")) {
        theT04_FertilityRatesByAgeGroup = new T04_FertilityRatesByAgeGroup("T04_FertilityRatesByAgeGroup", {12, 6});
    }
    CHECKPOINT("checkpoint: Allocate memory for 'T05_CohortFertility'");
    assert(!theT05_CohortFertility); 
    if (!is_suppressed_compute("T05_CohortFertility")) {
        theT05_CohortFertility = new T05_CohortFertility("T05_CohortFertility", {});
    }
    CHECKPOINT("checkpoint: Allocate memory for 'T06_BirthsByUnion'");
    assert(!theT06_BirthsByUnion); 
    if (!is_suppressed_compute("T06_BirthsByUnion")) {
        theT06_BirthsByUnion = new T06_BirthsByUnion("T06_BirthsByUnion", {7});
    }
    CHECKPOINT("checkpoint: Allocate memory for 'T07_FirstUnionFormation'");
    assert(!theT07_FirstUnionFormation); 
    if (!is_suppressed_compute("T07_FirstUnionFormation")) {
        theT07_FirstUnionFormation = new T07_FirstUnionFormation("T07_FirstUnionFormation", {12});
    }
    CHECKPOINT("checkpoint: Finished allocating memory for entity tables");

    // Derived table instantiation
    CHECKPOINT("checkpoint: Finished allocating memory for derived tables");

    // Entity set instantiation
    CHECKPOINT("checkpoint: Finished allocating memory for entity sets");

    CHECKPOINT("checkpoint: Finished ModelStartup");
}

// Model simulation
void RunModel(openm::IModel * const i_model)
{
    CHECKPOINT("checkpoint: Starting RunModel");
    // provide access to run-time interface for entities
    BaseEntity::i_model = i_model;

    // initialize entity tables
    CHECKPOINT("checkpoint: Initialize 'T01_LifeExpectancy'");
    if (theT01_LifeExpectancy) theT01_LifeExpectancy->initialize_accumulators();
    CHECKPOINT("checkpoint: Initialize 'T02_TotalPopulationByYear'");
    if (theT02_TotalPopulationByYear) theT02_TotalPopulationByYear->initialize_accumulators();
    CHECKPOINT("checkpoint: Initialize 'T03_FertilityByAge'");
    if (theT03_FertilityByAge) theT03_FertilityByAge->initialize_accumulators();
    CHECKPOINT("checkpoint: Initialize 'T04_FertilityRatesByAgeGroup'");
    if (theT04_FertilityRatesByAgeGroup) theT04_FertilityRatesByAgeGroup->initialize_accumulators();
    CHECKPOINT("checkpoint: Initialize 'T05_CohortFertility'");
    if (theT05_CohortFertility) theT05_CohortFertility->initialize_accumulators();
    CHECKPOINT("checkpoint: Initialize 'T06_BirthsByUnion'");
    if (theT06_BirthsByUnion) theT06_BirthsByUnion->initialize_accumulators();
    CHECKPOINT("checkpoint: Initialize 'T07_FirstUnionFormation'");
    if (theT07_FirstUnionFormation) theT07_FirstUnionFormation->initialize_accumulators();
    CHECKPOINT("checkpoint: Finished initializing entity tables");

    CHECKPOINT("checkpoint: Initialize simulation runtime (Event)");
    BaseEvent::initialize_simulation_runtime();
    CHECKPOINT("checkpoint: Initialize simulation runtime (Entity)");
    BaseEntity::initialize_simulation_runtime();

    int sub_id = i_model->subValueId();
    int sub_count = i_model->subValueCount();
    if (om_resource_use_on) {
        CHECKPOINT("checkpoint: Initialize resource use measurement");
        // reset resource use for entity tables
        om_T01_LifeExpectancy_resource_use_reset();
        om_T02_TotalPopulationByYear_resource_use_reset();
        om_T03_FertilityByAge_resource_use_reset();
        om_T04_FertilityRatesByAgeGroup_resource_use_reset();
        om_T05_CohortFertility_resource_use_reset();
        om_T06_BirthsByUnion_resource_use_reset();
        om_T07_FirstUnionFormation_resource_use_reset();
    } // om_resource_use_on


    CHECKPOINT("checkpoint: Call RunSimulation");
    RunSimulation(sub_id, sub_count, i_model); // Defined by the model framework, generally in a 'use' module
    CHECKPOINT("checkpoint: Returned from RunSimulation");



    CHECKPOINT("checkpoint: Finalize simulation runtime (Event)");
    BaseEvent::finalize_simulation_runtime();
    CHECKPOINT("checkpoint: Finalize simulation runtime (Entity)");
    BaseEntity::finalize_simulation_runtime();
    CHECKPOINT("checkpoint: Finished RunModel");
}

// Model shutdown method: outputs
void ModelShutdown(IModel * const i_model)
{
    // obtain simulation member to use for log messages
    int simulation_member = i_model->subValueId();

    // extract accumulators, and scale them to population size
    theLog->logFormatted("member=%d Compute entity tables", simulation_member);
    CHECKPOINT("checkpoint: Processing accumulators for 'T01_LifeExpectancy'");
    if (theT01_LifeExpectancy) theT01_LifeExpectancy->extract_accumulators();
    if (theT01_LifeExpectancy) theT01_LifeExpectancy->scale_accumulators();
    CHECKPOINT("checkpoint: Processing accumulators for 'T02_TotalPopulationByYear'");
    if (theT02_TotalPopulationByYear) theT02_TotalPopulationByYear->extract_accumulators();
    if (theT02_TotalPopulationByYear) theT02_TotalPopulationByYear->scale_accumulators();
    CHECKPOINT("checkpoint: Processing accumulators for 'T03_FertilityByAge'");
    if (theT03_FertilityByAge) theT03_FertilityByAge->extract_accumulators();
    if (theT03_FertilityByAge) theT03_FertilityByAge->scale_accumulators();
    CHECKPOINT("checkpoint: Processing accumulators for 'T04_FertilityRatesByAgeGroup'");
    if (theT04_FertilityRatesByAgeGroup) theT04_FertilityRatesByAgeGroup->extract_accumulators();
    if (theT04_FertilityRatesByAgeGroup) theT04_FertilityRatesByAgeGroup->scale_accumulators();
    CHECKPOINT("checkpoint: Processing accumulators for 'T05_CohortFertility'");
    if (theT05_CohortFertility) theT05_CohortFertility->extract_accumulators();
    if (theT05_CohortFertility) theT05_CohortFertility->scale_accumulators();
    CHECKPOINT("checkpoint: Processing accumulators for 'T06_BirthsByUnion'");
    if (theT06_BirthsByUnion) theT06_BirthsByUnion->extract_accumulators();
    if (theT06_BirthsByUnion) theT06_BirthsByUnion->scale_accumulators();
    CHECKPOINT("checkpoint: Processing accumulators for 'T07_FirstUnionFormation'");
    if (theT07_FirstUnionFormation) theT07_FirstUnionFormation->extract_accumulators();
    if (theT07_FirstUnionFormation) theT07_FirstUnionFormation->scale_accumulators();
    CHECKPOINT("checkpoint: Finished processing accumulators for entity tables");

    // compute table expressions using accumulators
    CHECKPOINT("checkpoint: Computing expressions for 'T01_LifeExpectancy'");
    if (theT01_LifeExpectancy) theT01_LifeExpectancy->compute_expressions();
    CHECKPOINT("checkpoint: Computing expressions for 'T02_TotalPopulationByYear'");
    if (theT02_TotalPopulationByYear) theT02_TotalPopulationByYear->compute_expressions();
    CHECKPOINT("checkpoint: Computing expressions for 'T03_FertilityByAge'");
    if (theT03_FertilityByAge) theT03_FertilityByAge->compute_expressions();
    CHECKPOINT("checkpoint: Computing expressions for 'T04_FertilityRatesByAgeGroup'");
    if (theT04_FertilityRatesByAgeGroup) theT04_FertilityRatesByAgeGroup->compute_expressions();
    CHECKPOINT("checkpoint: Computing expressions for 'T05_CohortFertility'");
    if (theT05_CohortFertility) theT05_CohortFertility->compute_expressions();
    CHECKPOINT("checkpoint: Computing expressions for 'T06_BirthsByUnion'");
    if (theT06_BirthsByUnion) theT06_BirthsByUnion->compute_expressions();
    CHECKPOINT("checkpoint: Computing expressions for 'T07_FirstUnionFormation'");
    if (theT07_FirstUnionFormation) theT07_FirstUnionFormation->compute_expressions();
    CHECKPOINT("checkpoint: Finished computing expressions for entity tables");

    theLog->logFormatted("member=%d Write output tables - start", simulation_member);

    extern int64_t report_table_write_progress(int member, int tableNumber, const char * name, int64_t lastTime);

    // write entity tables (accumulators) and release accumulators memory
    int64_t last_progress_ms = getMilliseconds();
    int n_table = 0;

    if (!is_suppressed_write("T01_LifeExpectancy", i_model)) {
        last_progress_ms = report_table_write_progress(simulation_member, ++n_table, "T01_LifeExpectancy", last_progress_ms);
        CHECKPOINT("checkpoint: Write 'T01_LifeExpectancy'");
        i_model->writeOutputTable("T01_LifeExpectancy", theT01_LifeExpectancy->n_cells, theT01_LifeExpectancy->acc_storage);
    }
    if (!is_suppressed_write("T02_TotalPopulationByYear", i_model)) {
        last_progress_ms = report_table_write_progress(simulation_member, ++n_table, "T02_TotalPopulationByYear", last_progress_ms);
        CHECKPOINT("checkpoint: Write 'T02_TotalPopulationByYear'");
        i_model->writeOutputTable("T02_TotalPopulationByYear", theT02_TotalPopulationByYear->n_cells, theT02_TotalPopulationByYear->acc_storage);
    }
    if (!is_suppressed_write("T03_FertilityByAge", i_model)) {
        last_progress_ms = report_table_write_progress(simulation_member, ++n_table, "T03_FertilityByAge", last_progress_ms);
        CHECKPOINT("checkpoint: Write 'T03_FertilityByAge'");
        i_model->writeOutputTable("T03_FertilityByAge", theT03_FertilityByAge->n_cells, theT03_FertilityByAge->acc_storage);
    }
    if (!is_suppressed_write("T04_FertilityRatesByAgeGroup", i_model)) {
        last_progress_ms = report_table_write_progress(simulation_member, ++n_table, "T04_FertilityRatesByAgeGroup", last_progress_ms);
        CHECKPOINT("checkpoint: Write 'T04_FertilityRatesByAgeGroup'");
        i_model->writeOutputTable("T04_FertilityRatesByAgeGroup", theT04_FertilityRatesByAgeGroup->n_cells, theT04_FertilityRatesByAgeGroup->acc_storage);
    }
    if (!is_suppressed_write("T05_CohortFertility", i_model)) {
        last_progress_ms = report_table_write_progress(simulation_member, ++n_table, "T05_CohortFertility", last_progress_ms);
        CHECKPOINT("checkpoint: Write 'T05_CohortFertility'");
        i_model->writeOutputTable("T05_CohortFertility", theT05_CohortFertility->n_cells, theT05_CohortFertility->acc_storage);
    }
    if (!is_suppressed_write("T06_BirthsByUnion", i_model)) {
        last_progress_ms = report_table_write_progress(simulation_member, ++n_table, "T06_BirthsByUnion", last_progress_ms);
        CHECKPOINT("checkpoint: Write 'T06_BirthsByUnion'");
        i_model->writeOutputTable("T06_BirthsByUnion", theT06_BirthsByUnion->n_cells, theT06_BirthsByUnion->acc_storage);
    }
    if (!is_suppressed_write("T07_FirstUnionFormation", i_model)) {
        last_progress_ms = report_table_write_progress(simulation_member, ++n_table, "T07_FirstUnionFormation", last_progress_ms);
        CHECKPOINT("checkpoint: Write 'T07_FirstUnionFormation'");
        i_model->writeOutputTable("T07_FirstUnionFormation", theT07_FirstUnionFormation->n_cells, theT07_FirstUnionFormation->acc_storage);
    }
    CHECKPOINT("checkpoint: Finished writing entity tables");
    // at this point table->acc[k][j] will cause memory access violation

    // write derived tables (measures) and release measures memory
    CHECKPOINT("checkpoint: Finished writing derived tables");
    // at this point table->measure[k][j] will cause memory access violation

    theLog->logFormatted("member=%d Write output tables - finish", simulation_member);

    // Entity table destruction
    theLog->logFormatted("member=%d Cleanup entity tables - start", simulation_member);
    if (theT01_LifeExpectancy) {
        CHECKPOINT("checkpoint: Free memory for 'T01_LifeExpectancy'");
        delete theT01_LifeExpectancy;
        theT01_LifeExpectancy = nullptr;
    }
    if (theT02_TotalPopulationByYear) {
        CHECKPOINT("checkpoint: Free memory for 'T02_TotalPopulationByYear'");
        delete theT02_TotalPopulationByYear;
        theT02_TotalPopulationByYear = nullptr;
    }
    if (theT03_FertilityByAge) {
        CHECKPOINT("checkpoint: Free memory for 'T03_FertilityByAge'");
        delete theT03_FertilityByAge;
        theT03_FertilityByAge = nullptr;
    }
    if (theT04_FertilityRatesByAgeGroup) {
        CHECKPOINT("checkpoint: Free memory for 'T04_FertilityRatesByAgeGroup'");
        delete theT04_FertilityRatesByAgeGroup;
        theT04_FertilityRatesByAgeGroup = nullptr;
    }
    if (theT05_CohortFertility) {
        CHECKPOINT("checkpoint: Free memory for 'T05_CohortFertility'");
        delete theT05_CohortFertility;
        theT05_CohortFertility = nullptr;
    }
    if (theT06_BirthsByUnion) {
        CHECKPOINT("checkpoint: Free memory for 'T06_BirthsByUnion'");
        delete theT06_BirthsByUnion;
        theT06_BirthsByUnion = nullptr;
    }
    if (theT07_FirstUnionFormation) {
        CHECKPOINT("checkpoint: Free memory for 'T07_FirstUnionFormation'");
        delete theT07_FirstUnionFormation;
        theT07_FirstUnionFormation = nullptr;
    }
    CHECKPOINT("checkpoint: Finished freeing memory for entity tables");
    theLog->logFormatted("member=%d Cleanup entity tables - finish", simulation_member);

    CHECKPOINT("checkpoint: Finished ModelShutdown");
    theLog->logFormatted("member=%d Completed.", simulation_member);
}

// Process shutdown: last entry point from user code before process exit
// All modelling threads are completed at this point, parameters and output tables memory released
// Any attempt to use parameters or output table may cause memory violation crush
void RunShutdown(bool i_isError, IRunBase * const i_runBase)
{
    // max memory usage
    auto [nMem, nMax] = getProcessMemorySize();

    if (nMax > 0) theLog->logFormatted("Process peak memory usage: %.2f MB", ((double)nMax / (1024.0 * 1024.0)));
    CHECKPOINT("checkpoint: Finished RunShutdown");
}

